--
-- Table structure for table `class_schedules`
--

DROP TABLE IF EXISTS `class_schedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `class_schedules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `academic_year_id` int(11) NOT NULL,
  `grade_level_id` int(11) NOT NULL,
  `lesson_period_id` int(11) NOT NULL,
  `end_lesson_period_id` int(11) DEFAULT NULL,
  `employee_id` int(11) NOT NULL,
  `subject_id` int(11) NOT NULL,
  `day` enum('Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday') NOT NULL,
  `day_of_week` tinyint(4) NOT NULL COMMENT '1=Monday ... 7=Sunday',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_class_schedule` (`academic_year_id`,`grade_level_id`,`day_of_week`,`lesson_period_id`),
  UNIQUE KEY `uq_teacher_schedule` (`academic_year_id`,`employee_id`,`day_of_week`,`lesson_period_id`),
  KEY `idx_day` (`day`),
  KEY `idx_grade_level` (`grade_level_id`),
  KEY `idx_employee` (`employee_id`),
  KEY `academic_year_id` (`academic_year_id`),
  KEY `subject_id` (`subject_id`),
  KEY `fk_class_schedules_period` (`lesson_period_id`),
  KEY `end_lesson_period_id` (`end_lesson_period_id`),
  CONSTRAINT `class_schedules_ibfk_1` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`),
  CONSTRAINT `class_schedules_ibfk_2` FOREIGN KEY (`grade_level_id`) REFERENCES `grade_levels` (`id`),
  CONSTRAINT `class_schedules_ibfk_3` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `class_schedules_ibfk_4` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`),
  CONSTRAINT `class_schedules_ibfk_5` FOREIGN KEY (`end_lesson_period_id`) REFERENCES `lesson_periods` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_class_schedules_period` FOREIGN KEY (`lesson_period_id`) REFERENCES `lesson_periods` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1765 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

