--
-- Table structure for table `grade_levels`
--

DROP TABLE IF EXISTS `grade_levels`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `grade_levels` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `education_unit_id` int(11) DEFAULT NULL,
  `teacher_id` int(11) DEFAULT NULL,
  `level` varchar(50) DEFAULT NULL,
  `category` varchar(255) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `capacity` int(11) NOT NULL DEFAULT 36 COMMENT 'Maximum number of students',
  `level_order` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_gl_unit` (`education_unit_id`),
  KEY `fk_gl_teacher` (`teacher_id`),
  CONSTRAINT `fk_gl_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `employees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_gl_unit` FOREIGN KEY (`education_unit_id`) REFERENCES `education_units` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
