INSERT INTO `news` VALUES (1,'Kegiatan Tasmi\' Al-Qur\'an, Pembinaan & Bukber','Berita Yayasan','Salah satu program rutin yang diselenggarakan di lingkungan Yayasan Assunnah Cirebon adalah kegiatan Tasmi’ Al-Qur’an bagi karyawan, baik ikhwan maupun akhwat. Kegiatan ini menjadi sarana untuk menjaga dan menguatkan hafalan Al-Qur’an di tengah kesibukan aktivitas kerja sehari-hari.','1774434296_3628.jpg',1,8,63,'2026-02-26 15:52:33'),(4,'Gladi Tes Kemampuan Akademik SDIT','Kegiatan Santri','Murid-murid SDIT Assunnah Cirebon melaksanakan kegiatan Gladi Tes Kemampuan Akademik sebagai bagian dari persiapan menghadapi evaluasi pembelajaran pada Tahun Pelajaran 2025/2026.','1774434362_7628.jpg',1,5,39,'2026-02-26 15:52:33');
