--
-- Table structure for table `student_class_history`
--

DROP TABLE IF EXISTS `student_class_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_class_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `student_id` int(11) NOT NULL,
  `class_id` int(11) NOT NULL,
  `academic_year_id` int(11) NOT NULL,
  `status` enum('ACTIVE','TRANSFERRED','DROPPED','PROMOTED','GRADUATED') DEFAULT 'ACTIVE',
  `joined_at` date NOT NULL,
  `left_at` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_placement` (`student_id`,`academic_year_id`),
  UNIQUE KEY `uq_student_year_class` (`student_id`,`academic_year_id`,`class_id`),
  UNIQUE KEY `uq_student_active_year` (`student_id`,`academic_year_id`,`status`),
  KEY `fk_sch_year` (`academic_year_id`),
  KEY `idx_student_lookup` (`student_id`,`academic_year_id`),
  KEY `idx_class_lookup` (`class_id`,`academic_year_id`),
  KEY `idx_sch_student` (`student_id`),
  KEY `idx_sch_class` (`class_id`),
  KEY `idx_sch_year` (`academic_year_id`),
  CONSTRAINT `fk_sch_class` FOREIGN KEY (`class_id`) REFERENCES `grade_levels` (`id`),
  CONSTRAINT `fk_sch_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_sch_year` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`),
  CONSTRAINT `student_class_history_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `student_class_history_ibfk_2` FOREIGN KEY (`class_id`) REFERENCES `grade_levels` (`id`),
  CONSTRAINT `student_class_history_ibfk_3` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years_old` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2071 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

