--
-- Table structure for table `tahfidz_memorization`
--

DROP TABLE IF EXISTS `tahfidz_memorization`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tahfidz_memorization` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `student_id` int(11) NOT NULL,
  `date` date NOT NULL,
  `surah_start` varchar(100) DEFAULT NULL,
  `ayat_start` int(11) DEFAULT NULL,
  `surah_end` varchar(100) DEFAULT NULL,
  `ayat_end` int(11) DEFAULT NULL,
  `total_baris` int(11) DEFAULT 0,
  `juz` int(11) DEFAULT NULL,
  `status` enum('Lancar','Kurang Lancar','Ulang','Ziyadah','Murajaah') DEFAULT 'Lancar',
  `notes` text DEFAULT NULL,
  `teacher_id` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

